function asFixture<T extends object>(raw: string, label: string): T {
  const parsed = JSON.parse(raw) as unknown;
  if (parsed !== undefined && parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {
    const g = (parsed as { graph?: unknown }).graph;
    if (g !== undefined) {
      if (typeof g !== 'object' || g === null || !Array.isArray((g as { nodes?: unknown }).nodes)) {
        throw new Error(`CALIBRATION_FIXTURE_INVALID: ${label} graph.nodes must be an array`);
      }
      const nodes = (g as { nodes: unknown[] }).nodes;
      for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];
        if (typeof node !== 'object' || node === null || Array.isArray(node)) {
          throw new Error(`CALIBRATION_FIXTURE_INVALID: ${label} graph.nodes[${i}] must be an object`);
        }
        const required = ['id', 'kind', 'name', 'file', 'line'] as const;
        for (const field of required) {
          if ((node as Record<string, unknown>)[field] === undefined) {
            throw new Error(`CALIBRATION_FIXTURE_INVALID: ${label} graph.nodes[${i}] missing required field '${field}'`);
          }
        }
      }
    }
    return parsed as T;
  }
  throw new Error(`CALIBRATION_FIXTURE_INVALID: ${label} parsed to a non-object`);
}

