function sourceLineQuote(targetRoot: string, relFile: string, line: number): string {
  try {
    const abs = path.resolve(targetRoot, relFile);
    const rootReal = realResolve(path.resolve(targetRoot));
    const realFile = realResolve(abs);
    if (!isWithinRoot(realFile, rootReal) && realFile !== rootReal) return "";
    // Read only a small window around the target line instead of the entire file.
    const AVG_LINE_LEN = 80;
    const WINDOW_LINES = 6; // 3 lines above + target + 2 below
    const startByte = Math.max(0, (line - 3) * AVG_LINE_LEN);
    const readLen = WINDOW_LINES * AVG_LINE_LEN + 256;
    const fd = fs.openSync(realFile, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
    try {
      const size = fs.fstatSync(fd).size;
      if (size === 0) return "";
      const actualStart = Math.min(startByte, size);
      const actualLen = Math.min(readLen, size - actualStart);
      const buf = Buffer.alloc(actualLen);
      fs.readSync(fd, buf, 0, actualLen, actualStart);
      const lines = buf.toString("utf-8").split("\n");
      // The target line is near the start of the window; offset accordingly.
      const localIdx = line - 1 - Math.floor(startByte / AVG_LINE_LEN);
      return (lines[Math.max(0, localIdx)] ?? "").trim().slice(0, 300);
    } finally {
      fs.closeSync(fd);
    }
  } catch {
    return "";
  }
}

