export function thresholdFromCost(c: CostMatrix): number {
  if (!(c.falseBlock >= 0 && Number.isFinite(c.falseBlock))) {
    throw new Error(`CALIBRATION_BAD_COST_MATRIX: falseBlock must be finite and non-negative (got ${c.falseBlock})`);
  }
  if (!(c.missed >= 0 && Number.isFinite(c.missed))) {
    throw new Error(`CALIBRATION_BAD_COST_MATRIX: missed must be finite and non-negative (got ${c.missed})`);
  }
  const denom = c.falseBlock + c.missed;
  if (denom <= 0) throw new Error("CALIBRATION_BAD_COST_MATRIX: the two costs must sum above zero");
  return c.falseBlock / denom;
}

