function canonical(value: unknown, seen?: WeakSet<object>): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
  if (seen?.has(value as object)) throw new PolicyError("MALFORMED", "circular reference detected in policy object");
  const next = seen ?? new WeakSet<object>();
  next.add(value as object);
  if (Array.isArray(value)) return `[${value.map(v => canonical(v, next)).join(",")}]`;
  const entries = Object.entries(value as Record<string, unknown>).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${canonical(v, next)}`).join(",")}}`;
}

